<template><view class="page"><view class="search-head"><u-search v-model="keyword" placeholder="姓名 / 手机号 / 订单号 / 卡种" :showAction="false" bgColor="#fff" @search="reload" @clear="reload"/><scroll-view scroll-x class="tabs"><view class="tabs-inner"><text v-for="t in tabs" :key="t.value" :class="{active:status===t.value}" @click="status=t.value;reload()">{{t.label}}</text></view></scroll-view></view><z-paging ref="paging" v-model="rows" :fixed="true" :paging-style="pagingStyle" @query="query"><template #empty><u-empty text="暂无开卡订单" mode="list"/></template><view class="list"><view v-for="row in rows" :key="row.id" class="order-card"><view class="head"><view><strong>{{row.holder_name}}</strong><text>{{mask(row.holder_mobile)}}</text></view><u-tag :text="financeText(row.finance_status)" :type="financeType(row.finance_status)" plain size="mini"/></view><view class="product"><text>{{row.product_name}}</text><strong>¥{{money(row.order_amount)}}</strong></view><view class="meta"><text>{{row.order_no}}</text><text>{{time(row.create_at)}} · {{row.issuer_name}}</text></view><view v-if="row.last_error" class="error">{{row.last_error}}</view></view></view></z-paging><view class="fab" @click="goCreate"><u-icon name="plus" color="#fff" size="25"/></view></view></template>
<script setup lang="ts">import{computed,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{getCardOrders}from'../../api';const keyword=ref(''),status=ref(''),rows=ref<any[]>([]),paging=ref<any>();const tabs=[{label:'全部',value:''},{label:'待收款',value:'pending'},{label:'部分收款',value:'partial'},{label:'已结清',value:'settled'},{label:'失败',value:'failed'}];const pagingStyle=computed(()=>({top:'176rpx',bottom:'0'}));const reload=()=>paging.value?.reload();const query=async(page:number,limit:number)=>{try{const r:any=await getCardOrders({keyword:keyword.value,finance_status:status.value,page,limit});paging.value?.complete(r?.data?.data||[])}catch{paging.value?.complete(false)}};const money=(v:any)=>Number(v||0).toFixed(2),mask=(v:string)=>/^\d{11}$/.test(v||'')?`${v.slice(0,3)}****${v.slice(-4)}`:(v||'—'),time=(v:any)=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}).slice(0,16):'—',financeText=(v:string)=>({pending:'待收款',partial:'部分收款',settled:'已结清',failed:'处理失败',refunded:'已退款'}[v]||v),financeType=(v:string)=>({settled:'success',failed:'error',partial:'warning',pending:'warning'}[v]||'info')as any;const goCreate=()=>uni.navigateTo({url:'/addon/hsx_member_card/pages/order/create'});onShow(reload)</script>
<style scoped>.page{min-height:100vh;background:#f3f4f6}.search-head{position:fixed;z-index:10;top:0;right:0;left:0;padding:18rpx 24rpx 0;background:#f3f4f6}.tabs{height:80rpx}.tabs-inner{display:flex;gap:14rpx;align-items:center;height:80rpx}.tabs text{padding:12rpx 24rpx;border-radius:24rpx;background:#fff;color:#64748b;white-space:nowrap}.tabs text.active{background:#3b6ef5;color:#fff}.list{padding:18rpx 24rpx}.order-card{margin-bottom:18rpx;padding:24rpx;border:1rpx solid #e6ebf2;border-radius:18rpx;background:#fff}.head,.product,.meta{display:flex;align-items:center;justify-content:space-between;gap:16rpx}.head>view{display:flex;align-items:center;gap:12rpx}.head text,.meta{color:#64748b;font-size:22rpx}.product{margin-top:20rpx;padding:18rpx 0;border-top:1rpx solid #eef2f7;border-bottom:1rpx solid #eef2f7}.product strong{color:#ea580c}.meta{margin-top:16rpx}.error{margin-top:14rpx;padding:12rpx;background:#fef2f2;color:#dc2626;font-size:21rpx}.fab{position:fixed;right:28rpx;bottom:50rpx;display:flex;width:94rpx;height:94rpx;border-radius:50%;background:#3b6ef5;align-items:center;justify-content:center;box-shadow:0 12rpx 28rpx rgba(59,110,245,.3)}</style>
